<?php
require_once __DIR__.'/config.php';
if(user()){header('Location:index.php');exit;}
$err='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['username']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$users=data_load('users.json');foreach($users as $x){if(strtolower($x['email'])===$email||strtolower($x['username'])===strtolower($name))$err='Ник или E-mail уже занят.';}if(!$err&&!preg_match('/^[A-Za-z0-9_]{3,24}$/',$name))$err='Некорректный ник.';if(!$err&&!filter_var($email,FILTER_VALIDATE_EMAIL))$err='Некорректный E-mail.';if(!$err&&strlen($pass)<8)$err='Пароль минимум 8 символов.';if(!$err){$id=count($users)+1;$token=bin2hex(random_bytes(24));$users[]=['id'=>$id,'username'=>$name,'email'=>$email,'password_hash'=>password_hash($pass,PASSWORD_DEFAULT),'email_verified'=>false,'verify_token'=>$token,'role'=>strtolower($email)===strtolower(ADMIN_EMAIL)?'admin':'user','banned_until'=>null,'ban_reason'=>'','last_ip'=>$_SERVER['REMOTE_ADDR']??'','created_at'=>date('c')];data_save('users.json',$users);$link=SITE_URL.'/verify.php?id='.$id.'&token='.$token;@mail($email,'GREFFRLEND: подтверждение E-mail','Подтвердите регистрацию: '.$link,'From: '.MAIL_FROM);$ok='Аккаунт создан. Проверьте почту для подтверждения E-mail.';}}
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Регистрация — GREFFRLEND</title><link rel="stylesheet" href="style.css"></head><body><main class="wrap"><div class="card form" style="margin:70px auto"><a class="logo" href="index.php">GREFFRLEND</a><h1>Регистрация</h1><?php if($err):?><div class="card danger"><?=e($err)?></div><?php endif;?><?php if($ok):?><div class="card success"><?=e($ok)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Ник</label><input name="username" required><label>E-mail</label><input type="email" name="email" required><label>Пароль</label><input type="password" name="password" minlength="8" required><button class="btn">Создать аккаунт</button></form><p class="muted">После подтверждения адреса <?=e(ADMIN_EMAIL)?> получает роль admin.</p></div></main></body></html>